"""Generate identical palette and layout constants for the three native renderers."""
import json,sys
from pathlib import Path
root=Path(__file__).resolve().parents[1]
d=json.loads((root/'shared/design.json').read_text(encoding='utf-8'))
colors=d['colors']
outputs={
'apps/web/app/design-tokens.css':':root {\n'+''.join(f'  --{key}: {value};\n' for key,value in colors.items())+'}\n',
'apps/android/app/src/main/java/com/sevil/learncompanion/DesignTokens.kt':'// Generated by scripts/sync-design.py\npackage com.sevil.learncompanion\nimport androidx.compose.ui.graphics.Color\nobject Design {\n'+''.join(f'    val {key}=Color(0xFF{value[1:]})\n' for key,value in colors.items())+f'    const val compactBelow={d["compactBelow"]}\n    const val expandedFrom={d["expandedFrom"]}\n    const val radius={d["radius"]}\n    const val touchTarget={d["touchTarget"]}\n'+'}\n',
'apps/ios/SeviL/DesignTokens.swift':'// Generated by scripts/sync-design.py\nimport SwiftUI\nenum Design {\n'+''.join(f'    static let {key}=Color(red:{int(value[1:3],16)/255:.6f},green:{int(value[3:5],16)/255:.6f},blue:{int(value[5:7],16)/255:.6f})\n' for key,value in colors.items())+f'    static let compactBelow: CGFloat={d["compactBelow"]}\n    static let expandedFrom: CGFloat={d["expandedFrom"]}\n    static let radius: CGFloat={d["radius"]}\n    static let touchTarget: CGFloat={d["touchTarget"]}\n'+'}\n'
}
for name,content in outputs.items():
 p=root/name
 if '--check' in sys.argv:
  if not p.exists() or p.read_text(encoding='utf-8')!=content:raise SystemExit('Run python scripts/sync-design.py')
 else:p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8',newline='\n')
print('Shared design tokens are aligned across Android, iOS and web.')
